import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_direct(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 total,
    .param .u32 batch,
    .param .u32 cin,
    .param .u32 hin,
    .param .u32 win,
    .param .u32 cout,
    .param .u32 kh,
    .param .u32 kw,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 hout,
    .param .u32 wout,
    .param .u32 has_bias
)
{
    .reg .pred p0, p1, p2, p3, p4;
    .reg .u32 uTid, uNtid, uCta, uIdx;
    .reg .u32 uTotal, uN, uCin, uH, uW, uCout, uKH, uKW;
    .reg .u32 uStrideH, uStrideW, uPadH, uPadW, uDilH, uDilW, uHout, uWout, uHasBias;
    .reg .u32 uT0, uT1, uOw, uOh, uOc, uBatch, uIc, uKh, uKw, uIh, uIw, uOff, uHasB;
    .reg .s32 sOh, sOw, sStrideH, sStrideW, sPadH, sPadW, sDilH, sDilW, sH, sW, sIh, sIw, sKh, sKw;
    .reg .u64 rdIn, rdW, rdB, rdOut, rdOff, rdAddr;
    .reg .f32 fAcc, fX, fWt, fBs;

    ld.param.u64 rdIn, [in_ptr];
    ld.param.u64 rdW, [w_ptr];
    ld.param.u64 rdB, [b_ptr];
    ld.param.u64 rdOut, [out_ptr];
    ld.param.u32 uTotal, [total];
    ld.param.u32 uN, [batch];
    ld.param.u32 uCin, [cin];
    ld.param.u32 uH, [hin];
    ld.param.u32 uW, [win];
    ld.param.u32 uCout, [cout];
    ld.param.u32 uKH, [kh];
    ld.param.u32 uKW, [kw];
    ld.param.u32 uStrideH, [stride_h];
    ld.param.u32 uStrideW, [stride_w];
    ld.param.u32 uPadH, [pad_h];
    ld.param.u32 uPadW, [pad_w];
    ld.param.u32 uDilH, [dil_h];
    ld.param.u32 uDilW, [dil_w];
    ld.param.u32 uHout, [hout];
    ld.param.u32 uWout, [wout];
    ld.param.u32 uHasBias, [has_bias];

    mov.u32 uTid, %tid.x;
    mov.u32 uNtid, %ntid.x;
    mov.u32 uCta, %ctaid.x;
    mad.lo.u32 uIdx, uCta, uNtid, uTid;
    setp.ge.u32 p0, uIdx, uTotal;
    @p0 bra L_DONE;

    rem.u32 uOw, uIdx, uWout;
    div.u32 uT0, uIdx, uWout;
    rem.u32 uOh, uT0, uHout;
    div.u32 uT1, uT0, uHout;
    rem.u32 uOc, uT1, uCout;
    div.u32 uBatch, uT1, uCout;

    cvt.s32.u32 sOh, uOh;
    cvt.s32.u32 sOw, uOw;
    cvt.s32.u32 sStrideH, uStrideH;
    cvt.s32.u32 sStrideW, uStrideW;
    cvt.s32.u32 sPadH, uPadH;
    cvt.s32.u32 sPadW, uPadW;
    cvt.s32.u32 sDilH, uDilH;
    cvt.s32.u32 sDilW, uDilW;
    cvt.s32.u32 sH, uH;
    cvt.s32.u32 sW, uW;

    mov.f32 fAcc, 0f00000000;
    mov.u32 uIc, 0;
L_IC:
    setp.ge.u32 p0, uIc, uCin;
    @p0 bra L_IC_DONE;
    mov.u32 uKh, 0;
L_KH:
    setp.ge.u32 p0, uKh, uKH;
    @p0 bra L_KH_DONE;
    cvt.s32.u32 sKh, uKh;
    mul.lo.s32 sIh, sOh, sStrideH;
    sub.s32 sIh, sIh, sPadH;
    mad.lo.s32 sIh, sKh, sDilH, sIh;
    setp.lt.s32 p0, sIh, 0;
    setp.ge.s32 p1, sIh, sH;
    or.pred p2, p0, p1;
    @p2 bra L_KH_NEXT;
    cvt.u32.s32 uIh, sIh;
    mov.u32 uKw, 0;
L_KW:
    setp.ge.u32 p0, uKw, uKW;
    @p0 bra L_KW_DONE;
    cvt.s32.u32 sKw, uKw;
    mul.lo.s32 sIw, sOw, sStrideW;
    sub.s32 sIw, sIw, sPadW;
    mad.lo.s32 sIw, sKw, sDilW, sIw;
    setp.lt.s32 p0, sIw, 0;
    setp.ge.s32 p1, sIw, sW;
    or.pred p2, p0, p1;
    @p2 bra L_TAP_NEXT;
    cvt.u32.s32 uIw, sIw;

    mad.lo.u32 uOff, uBatch, uCin, uIc;
    mad.lo.u32 uOff, uOff, uH, uIh;
    mad.lo.u32 uOff, uOff, uW, uIw;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdIn, rdOff;
    ld.global.nc.f32 fX, [rdAddr];

    mad.lo.u32 uOff, uOc, uCin, uIc;
    mad.lo.u32 uOff, uOff, uKH, uKh;
    mad.lo.u32 uOff, uOff, uKW, uKw;
    cvt.u64.u32 rdOff, uOff;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdW, rdOff;
    ld.global.nc.f32 fWt, [rdAddr];

    fma.rn.f32 fAcc, fX, fWt, fAcc;
L_TAP_NEXT:
    add.u32 uKw, uKw, 1;
    bra L_KW;
L_KW_DONE:
L_KH_NEXT:
    add.u32 uKh, uKh, 1;
    bra L_KH;
L_KH_DONE:
    add.u32 uIc, uIc, 1;
    bra L_IC;
L_IC_DONE:

    setp.eq.u32 p0, uHasBias, 0;
    @p0 bra L_STORE;
    cvt.u64.u32 rdOff, uOc;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdB, rdOff;
    ld.global.f32 fBs, [rdAddr];
    add.f32 fAcc, fAcc, fBs;
L_STORE:
    cvt.u64.u32 rdOff, uIdx;
    shl.b64 rdOff, rdOff, 2;
    add.u64 rdAddr, rdOut, rdOff;
    st.global.f32 [rdAddr], fAcc;
L_DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("conv2d_direct")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        n, cin, hin, win = x.shape
        cout = self.conv2d.out_channels
        kh, kw = self.conv2d.kernel_size
        sh, sw = self.conv2d.stride
        ph, pw = self.conv2d.padding
        dh, dw = self.conv2d.dilation
        hout = (hin + 2 * ph - dh * (kh - 1) - 1) // sh + 1
        wout = (win + 2 * pw - dw * (kw - 1) - 1) // sw + 1
        out = torch.empty((n, cout, hout, wout), device=x.device, dtype=x.dtype)
        total = n * cout * hout * wout
        w = self.conv2d.weight
        b = self.conv2d.bias
        has_bias = 0 if b is None else 1
        if b is None:
            b = w
        grid_x = (total + 255) // 256
        _get_ptx_module().launch(
            "conv2d_direct",
            grid=(grid_x, 1, 1),
            block=(256, 1, 1),
            arguments=[
                x, w, b, out,
                i32(total), i32(n), i32(cin), i32(hin), i32(win),
                i32(cout), i32(kh), i32(kw), i32(sh), i32(sw),
                i32(ph), i32(pw), i32(dh), i32(dw),
                i32(hout), i32(wout), i32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

